INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C01','전압 강하·방전 곡선','candidate','empirical','partially-verified','V_load = V_oc − I·R_int, 저전압 컷오프','셀 전압 4.2→3.7V, 환산 평균 4.0V(CL07). 방전곡선·내부저항 수식은 미확보');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C02','ESC 전류 마진','candidate','empirical','verified','I_ESC_rated ≥ I_motor_max (논문 식 66). 여유 계수는 논문에 없음',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C03','고도·온도에 따른 공기밀도','implemented','empirical','verified','ρ = 273/(273+T)·(1−0.0065h/(273+T))^5.2561·ρ0 (ρ0=1.293)','고도 입력(선택)이 있으면 호버링 전력·고정익 날개폭에 반영. 디스크 로딩 한계 DL은 밀도 보정하지 않음(근거 없음). 고도 미입력은 해면 15°C(≈1.2257)');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C04','전진 비행 전력(속도별)','candidate','empirical','partially-verified','P(v) 곡선, 최적 순항 속도','전진 비행이 호버보다 전력이 낮은 구간 존재(CL09), 최적 속도에서 EPM∝질량·v_opt∝√m(CL11,12). 전력 곡선 수식 자체는 아직 코드화 안 함');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C05','모터 토크-KV-전압 관계','candidate','empirical',NULL,'RPM ≈ KV·V·부하계수, τ = Kt·I',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C06','무게중심·질량 분포','candidate','empirical',NULL,'Σ(m_i·r_i)/Σm_i 범위 내',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C07','전원 배선 전류·전선 굵기','candidate','empirical',NULL,'I ≤ 허용전류(AWG)',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C08','통신 링크 예산','candidate','empirical',NULL,'Pr = Pt+Gt+Gr−FSPL−손실, 마진 ≥ 10dB',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C09','단위·차원 일관성','candidate','empirical',NULL,'모든 수치의 단위 변환 검사',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('C10','규칙 간 모순 검사','candidate','empirical',NULL,'서로 다른 규칙이 같은 양을 다르게 예측하면 경고',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R01','호버링 전력(운동량 이론)','implemented','empirical','partially-verified','P = N·(m·g/N)^1.5 / sqrt(2·ρ_air·A) / (FM·η)','유도 동력항 형태는 Gong 2022 식(5)로 확인. 종합효율 FM·η는 실제 기체 4종에서 역산(CL15: 0.32~0.47)해 보수 0.36(0.45×0.8), 낙관 0.48(0.6×0.8)로 조정(2026-10-19, 이전 0.48/0.675). n=4라 표본 작음 — 기체 데이터가 늘면 재보정. 공기밀도는 C03 ISA 식');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R02','로터 원판 면적','implemented','definition','verified','D = wheelbase·sin(π/N)·0.95, A = π(D/2)²','인접 프롭 겹침 방지 기하. 0.95는 가정');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R03','추력 대비 중량비','implemented','empirical','verified','T_max ≥ 2·m·g','Dai 2019: 일반 멀티로터 γ=0.5 선택 → T_max=2·T_hover. 관행 값이지 물리 상수는 아님');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R04','디스크 로딩 한계','implemented','empirical','partially-verified','2·m ≤ N·A·DL','현실적 최대 추력 면적밀도 가정');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R05','배터리 에너지 수지','implemented','empirical','verified-with-derived','m_bat = P·t / (DoD·e_pack)','2026-10-19 조정: 보수 155=카탈로그 40개 중앙값(CL10, 300g 이상 163), 낙관 207=카탈로그 상위 5번째 값. 논문 140(CL02)은 하한 참고값. 이전 값 180/280은 근거 없는 가정이었음 | 2026-10-20: 낙관 207은 LiPo 팩 범위(136~173, CL16)를 넘고 Li-ion 팩(NMC 240÷1.15≈209) 수준. 낙관 가정은 ''Li-ion 팩 사용 시''로 해석해야 함 | 2026-10-20: 고정익용 장시간 배터리는 제조사 표기 265~450Wh/kg(CL23, 저방전율·셀/팩 혼재·미검증) — 낙관 207은 멀티로터 고방전율 기준으로 유지');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R06','구조 질량 비율','implemented','empirical','partially-verified','m_struct+avionics = ef·m','2026-10-20 검토: 페이로드 맞춤 기체 실측 역산 0.29~0.42(CL22)와 보수 0.45·낙관 0.30이 같은 범위라 유지. 범용 기체는 0.56~0.71. 논문 CL06(추진계>70%)은 정의가 달라 직접 비교 불가. 구조 질량은 크기에 따라 고정분이 있어 비율 하나로는 한계(AeroEval은 휠베이스·클래스별 보정 사용, CL21)');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R07','평균 속도 상한','implemented','empirical','partially-verified','v_req = R/t ≤ v_max',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R08','고정익 순항 에너지','implemented','empirical','partially-verified','b_f = g·v·t / (L/D·η_p·DoD·e_pack)','2026-10-20 검토(논문 14편·claim 29건, 대부분 모델/설계 추정): 상수 유지. 근거 대조 — L/D 보수 9: 소형 고정익 활공비 실측 9.83·7.10(P2605.15619)과 부합 / 낙관 14: NASA Lift+Cruise 순항 L/D 13.5(모델, 저자가 항력 과대 가능성 언급)와 부합. 프롭 효율 etaP 0.65~0.80: BEMT 모델값 0.7733(실측 아님)뿐이라 실측 근거 없음. VTOL 추가 질량 10%/5%: 실기체 QuadPlane 배터리 15%·추가 구조 별도 근거 부족. CLmax 1.2: 타일시터 가정 1.5(인용 가정)보다 보수적. VTOL 호버/순항 전력비 약 2.7배(NederDrone 실측 1500W vs 550W)가 실측으로 확인됨 — 현재 엔진은 호버 구간을 별도 계산하지 않고 vtolExtra 질량으로만 반영');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R09','배터리 Wh = V×Ah','implemented','definition','partially-verified','Wh = V·Ah','정의식이라 출처 불필요. 허용오차 0.98만 가정');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R10','시험표 추력-전류 보간','implemented','definition','partially-verified','선형 보간, 시험 범위 밖 외삽 금지','제조사 시험표 데이터에 의존. 시험 조건(전압·프롭) 일치 시에만 유효');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R11','C-rate 방전 한계','implemented','definition','verified','I_max ≤ C·Ah','제조사 표기 C값 신뢰 가정');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R12','프롭 지름 ≤ 축거 한계','implemented','heuristic','partially-verified','d_prop ≤ D_max + 0.5in',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R13','부품 질량 합 한계','implemented','heuristic','partially-verified','Σm_parts ≤ 1.15·AUW',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R14','프레임 질량 상한','implemented','heuristic','partially-verified','m_frame ≤ 0.45·AUW','2026-10-20: 실측 프레임 질량비 7.1%(QuadSoft 섀시)·약 23.5%(3DFiT F450급)로 상한 0.45는 느슨하지만 모순 없음(상한 용도)');
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R15','체공시간 판정 일관성','implemented','definition','partially-verified','HW 배터리 Wh ≥ 필요 Wh 이면 충족',NULL);
INSERT INTO rules (id,name,status,kind,source_status,formula,note) VALUES ('R16','통신 대역 상식','implemented','heuristic','verified','협대역(LoRa류)은 영상 불가, 영상은 Mbps급','현재는 프롬프트 문구일 뿐 코드 판정 아님');
