INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL10',NULL,NULL,NULL,'수집 카탈로그의 팩 에너지밀도','Wh/kg = (mAh/1000·V_nom)/(kg)','전체 40개 중앙값 155, 300g 이상 28개 중앙값 163, 최소 90, 최대 311','Wh/kg','제조사 표기 무게·용량·공칭 전압으로 계산. 311·285는 대용량·저방전율 팩으로 특이값. 팩 무게에 케이블·커넥터 포함 여부는 제조사 표기에 따름',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL11',NULL,'2501.03102',NULL,'멀티로터 최적 전진 에너지','미터당 에너지(EPM)와 질량의 관계','최적 속도에서 EPM/m는 질량과 무관한 상수 → 최적 EPM은 질량에 비례','-','정속 전진 비행, 에너지 최적 속도에서만 성립. 임의 속도에서는 성립하지 않음. 1차 원리 모델 기반 해석·시뮬레이션',NULL,'paper','verified','high',0,'reported',NULL);
