INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL22',NULL,NULL,NULL,'비배터리·비페이로드 질량비(구조·추진·전장 합) 실측 역산','ef = 1 − 배터리비 − 페이로드비','페이로드 맞춤 배달 기체 0.42(2.57kg급)·0.29(24kg급); 페이로드 없는 범용 기체 F450 0.68·X500 0.56·T650 0.71·X650 0.63','-','배달 기체 값은 Zhang 2021 표를 P2604.07514가 인용한 2차 데이터. 범용 기체 값은 CL13·CL14의 총중량과 배터리 Wh(Wh/150 가정)에서 역산해 오차가 큼. 두 집단은 설계 목적이 다름(페이로드 맞춤 대 범용)',NULL,'derived','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL23',NULL,NULL,NULL,'고정익·장시간 비행용 배터리 제조사 표기 비에너지','Wh/kg (제조사 사양 문구 표기)','23개 제품 265~450Wh/kg, 중앙값 330 (Molicel P50B 265, Tattu 반고체·UHV 팩 280~380, Amprius SiCore 450)','Wh/kg','제조사 공식 페이지에 인쇄된 값. 셀 단위/팩 단위가 제품마다 다르고(Amprius는 셀), 방전율 10C 이하 저전류 조건. 멀티로터 호버처럼 고방전율 용도의 실효값이 아님. 제조사 표기라 독립 검증 아님',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL24',NULL,'2607.22768',NULL,'인접 프롭 간극 안전계수 (tip-clearance safety factor)','ε','0.05','-','MDO 논문의 기하 제약 D_p ≤ (1−ε)·W·sin(π/N_r). 쿼드 0.672·W, 헥사 0.475·W, 옥토 0.364·W(ε=0.05 적용). 설계 선택값이며 물리 상수는 아님',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL25',NULL,NULL,NULL,'LiPo 최대 방전 전류 = C 등급 × 용량(Ah)','I_max','C × Ah','A','제조사 기술 블로그의 정의. 연속 정격 기준이며 짧은 펄스 한계는 더 높을 수 있고, C 등급은 내부저항 변화에 따라 달라지는 상한',NULL,'manufacturer','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL26',NULL,NULL,NULL,'LoRa 변조 데이터 속도 범위','data rate','250 bps ~ 11 kbps (FSK 최대 50 kbps)','bps','LoRaWAN 지역 규정에 따라 달라짐(북미 최소 0.9 kbps). EU868 기본 채널 0.3~5 kbps. 480p H.264 영상은 약 1.8 Mbps가 필요해 수백 배 부족',NULL,'manufacturer','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL27',NULL,NULL,NULL,'질량 추정 불확실성 여유(contingency) — 설계 성숙도별','mass contingency','Concept 25% / Design 15% / Prior Build 7.5% / Fabrication 4% / Flight Build 2%','%','우주선(THEMIS 프로젝트) 사례로 UAV가 아님. 설계 단계 15%가 R13 허용오차 15%와 크기가 같다는 비교 근거일 뿐 UAV 직접 근거는 아님',NULL,'derived','verified','low',0,'cited-secondary',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL28',NULL,'2607.22768',NULL,'DIY 기체 20기의 MTOW 예측 오차','MTOW MAPE','26.1% (95% CI 18.5%–33.7%)','%','AeroEval 엔진을 DIY 드론 20기에 적용한 결과. 상용 기체 대상은 7.2%(P2607.22768-09)',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL29',NULL,NULL,NULL,'DJI S1000 센터 프레임 질량 ÷ 이륙중량','frame mass fraction','1330g ÷ 6.0~11.0kg = 약 12~22%','-','센터 프레임(랜딩기어 마운트·서보 포함)만의 질량이고 암은 제외. 제조사 공식 사양의 두 값으로 계산한 파생값',NULL,'manufacturer','sourced','medium',0,'derived',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL30',NULL,'2607.22768',NULL,'설계 모델의 구조 질량 분율 하한','f_struct,min','max(0.06, min(0.20, 0.05 + 0.05W))','-','AeroEval 설계 모델의 가정식(W는 논문 정의 변수). 실측이 아니라 모델 가정',NULL,'paper','verified','medium',0,'model-assumption',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL31',NULL,'1801.02938',NULL,'소형 UAV 설계 디스크 로딩','disc loading','90 N/m² (약 9.2 kgf/m²)','N/m²','가변 피치 쿼드로터 복엽 VTOL 설계 논문이 선택한 기준 설계값. R04 상수(보수 60·낙관 90 kgf/m²)는 ''현실적 최대 추력 면적밀도''라 이 호버 설계값보다 6~10배 크다 — 같은 양이 아니므로 직접 비교 불가',NULL,'paper','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL32',NULL,NULL,NULL,'DJI Matrice 350 RTK 최대 수평 속도','max horizontal speed','23','m/s','기체 최대 속도이지 임무 평균 속도가 아님. 최대 이륙 무게 9.2kg',NULL,'manufacturer','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL33',NULL,NULL,NULL,'DJI Agras T40 최대 비행·작동 속도','max flight speed','10','m/s','농업용 방제 드론. 작업 속도 제한이 포함된 값',NULL,'manufacturer','verified','high',0,'reported',NULL);
INSERT INTO claims (id,document_id,paper_id,subject_id,subject_text,predicate,object_value,unit,conditions,domain,origin,status,confidence,contested,evidence_kind,topic) VALUES ('CL34',NULL,'2511.05426',NULL,'인접 프로펠러 유닛 축 간격','inter-axis distance / propeller diameter','1.5','배','FlexiQuad 확장 모델 설계값. 식 D ≤ W·sin(π/N)·(1−ε)에 대입하면 ε≈0.33에 해당(저자 계산). 일반 쿼드의 0.05와는 다른 설계 철학',NULL,'paper','verified','high',0,'reported',NULL);
