INSERT INTO evidence (id,claim_id,source_id,locator,quote,evidence_type,verified,verification_method,support_score,support_detail) VALUES ('ev:f3632465c0bd','P2506.08386-01','src:945ffcc1e787','Sec. V, Battery Consumption','Battery Consumption: In our tests, the 5G Aero battery, with a capacity of 83Wh, provides an average of 5 minutes and 2 seconds of flight time without the 5G module turned on. When 5G transmissions are active, the average flight duration decreases by approximately 1%, resulting in an average flight time of roughly 4 minutes and 59 seconds.','verbatim-quote',1,'pdf-quote-match',NULL,NULL);
INSERT INTO evidence (id,claim_id,source_id,locator,quote,evidence_type,verified,verification_method,support_score,support_detail) VALUES ('ev:f36eb25ed7cf','W:d4d1db3a1b13','src:fb43a067feb7',NULL,'NotebookLM의 답변이나 그래프의 연결은 중간 가설이며, 원본을 확인한 뒤에만 장기 지식으로 승격한다.','wiki-summary',0,'unresolved',NULL,'확인 불가');
